3	import { useEffect, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  getExportUrl,
7	  getRequirements,
8	  getScenarios,
9	  type Requirement,
10	  type Scenario,
11	} from "@/src/lib/api";
12	import { categoryLabel } from "@/src/components/badges";
13	import { ScoreBar } from "@/src/components/ScoreBar";
14	import { ThemeToggle } from "@/src/components/ThemeToggle";
15	
16	const DEFAULT_SCENARIO_ID = "G60-US";
17	
18	export default function RequirementsPage() {
19	  const router = useRouter();
20	
21	  const [scenarios, setScenarios] = useState<Scenario[] | null>(null);
22	  const [scenarioId, setScenarioId] = useState<string>(DEFAULT_SCENARIO_ID);
23	  const [requirements, setRequirements] = useState<Requirement[] | null>(null);
24	  const [error, setError] = useState<string | null>(null);
25	  const [isFetching, setIsFetching] = useState(true);
26	
27	  const [promptText, setPromptText] = useState("");
28	  const [promptNote, setPromptNote] = useState<string | null>(null);
29	
30	  // Szenarien einmal laden; Standard bleibt G60-US, falls vorhanden, sonst erstes Szenario.
31	  useEffect(() => {
32	    getScenarios()
33	      .then((loaded) => {
34	        setScenarios(loaded);
35	        if (!loaded.some((s) => s.id === DEFAULT_SCENARIO_ID) && loaded[0]) {
36	          setScenarioId(loaded[0].id);
37	        }
38	      })
39	      .catch((err: Error) => setError(err.message));
40	  }, []);
41	
42	  // Anforderungen neu laden bei Szenario-Wechsel.
43	  useEffect(() => {
44	    if (!scenarioId) return;
45	    let cancelled = false;
46	    (async () => {
47	      setIsFetching(true);
48	      try {
49	        const loadedRequirements = await getRequirements(scenarioId);
50	        if (cancelled) return;
51	        setRequirements(loadedRequirements);
52	        setError(null);
53	      } catch (err) {
54	        if (cancelled) return;
55	        setError((err as Error).message);
56	      } finally {
57	        if (!cancelled) setIsFetching(false);
58	      }
59	    })();
60	    return () => {
61	      cancelled = true;
62	    };
63	  }, [scenarioId]);
64	
65	  const isLoading = scenarios === null || isFetching || requirements === null;
66	
67	  /** Platzhalter: Das Prompt-Feld ist noch nicht ans Backend angebunden (eigenes Ticket). */
68	  function handlePromptSubmit() {
69	    const text = promptText.trim();
70	    if (!text) return;
71	    console.log("[prompt submit - placeholder, not wired to backend yet]", text);
72	    setPromptNote(`Received: "${text}" — not connected to the backend yet.`);
73	    setPromptText("");
74	  }
75	
76	  return (
77	    <div className="flex min-h-screen flex-col">
78	      {/* Top bar: volle Breite, Platz für weitere Elemente später. Halbtransparent, damit der Shader-Hintergrund durchscheint. */}
79	      <header className="w-full border-b border-zinc-200 bg-white backdrop-blur-sm dark:border-zinc-800 dark:bg-zinc-950">
80	        <div className="flex flex-wrap items-center justify-between gap-4 px-6 py-4">
81	          <div>
82	            <h1 className="text-xl font-semibold text-[#0b1f3a] dark:text-zinc-100">Spec Checker</h1>
83	            <p className="text-sm text-zinc-500 dark:text-zinc-400">Prioritized requirements for product decisions</p>
